def x_has_commercial_data__mutmut_orig(cable: CableRow) -> bool:
    commercial_keys = (
        "price_per_meter",
        "stock_quantity_m",
        "stock_status",
        "lead_time_days",
        "supplier_name",
        "supplier_priority",
        "is_preferred",
        "order_multiple_m",
        "min_order_quantity_m",
        "article",
        "accessory_total_cost",
        "accessory_cost_total",
        "accessory_cost_per_circuit",
    )
    for key in commercial_keys:
        value = cable.get(key)
        if value is None and isinstance(cable.get("params"), dict):
            value = _nested_commercial_value(cable, key)
        if key == "stock_status" and value == "unknown":
            continue
        if value not in (None, "", False):
            return True
    return False


